function entry(id, component, label, location, values, defaultValue, source, options = {}) {
    return {
        id, component, label, location, values, default: defaultValue,
        scope: "user", status: "documented", evidence: "app",
        sources: [source], requires: [], conflicts: [], caveats: [],
        ...options,
    };
}

